310→// GitOutput runs a git command in the given directory, returns its trimmed
311→// stdout, and fails the test on error.
312→func GitOutput(t *testing.T, dir string, args ...string) string {
313→	t.Helper()
314→
315→	cmd := exec.Command("git", args...)
316→	if dir != "" {
317→		cmd.Dir = dir
318→	}
319→
320→	out, err := cmd.Output()
321→	if err != nil {
322→		var stderr string
323→		ee := &exec.ExitError{}
324→		if errors.As(err, &ee) {
325→			stderr = string(ee.Stderr)
326→		}
327→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
328→	}
329→
330→	return strings.TrimSpace(string(out))
331→}
