432→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
433→// the initial commit. Returns the bare repo path.
434→func SetupBareRemote(t *testing.T, s *RepoState) string {
435→	t.Helper()
436→
437→	var bareDir string
438→	if os.Getenv("E2E_KEEP_REPOS") != "" {
439→		var err error
440→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
441→		if err != nil {
442→			t.Fatalf("create bare remote dir: %v", err)
443→		}
444→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
445→	} else {
446→		bareDir = t.TempDir()
447→	}
448→
449→	Git(t, bareDir, "init", "--bare")
450→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
451→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
452→	return bareDir
453→}
