//go:build e2e

package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
		return
	}
	if _, err := exec.LookPath("kiro-cli"); err != nil {
		return
	}
	Register(&Kiro{})
	// Kiro uses Amazon Q API which may have rate limits
	RegisterGate("kiro", 1)
}

// Kiro implements the Agent interface for Amazon's Kiro CLI.
type Kiro struct{}

func (k *Kiro) Name() string               { return "kiro" }
func (k *Kiro) Binary() string             { return "kiro-cli" }
func (k *Kiro) EntireAgent() string        { return "kiro" }
func (k *Kiro) PromptPattern() string      { return `❯` }
func (k *Kiro) TimeoutMultiplier() float64 { return 1.5 }

func (k *Kiro) IsTransientError(out Output, _ error) bool {
	combined := out.Stdout + out.Stderr
	for _, p := range []string{"overloaded", "rate limit", "503", "529", "throttl"} {
		if strings.Contains(strings.ToLower(combined), p) {
			return true
		}
	}
	return false
}

func (k *Kiro) Bootstrap() error {
	// kiro-cli uses Amazon Q / Builder ID auth.
	// On CI, ensure the user is logged in; locally, auth is handled by the desktop app.
	if os.Getenv("CI") == "" {
		return nil
	}
	// Verify login status — fail fast if not authenticated.
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "kiro-cli", "whoami")
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("kiro-cli auth check failed (run `kiro-cli login`): %s", out)
	}
	return nil
}

func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	args := []string{"chat", "--no-interactive", "-a", prompt}
	if cfg.Model != "" {
		args = []string{"chat", "--no-interactive", "-a", "--model", cfg.Model, prompt}
	}

	cmd := exec.CommandContext(ctx, k.Binary(), args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	displayArgs := []string{"chat", "--no-interactive", "-a", fmt.Sprintf("%q", prompt)}
	return Output{
		Command:  k.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("kiro-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, nil, k.Binary(), "chat", "-a")
	if err != nil {
		return nil, err
	}

	// Wait for the prompt indicator
	if _, err := s.WaitFor(`❯`, 15*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for kiro startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

package kiro

// hookInputRaw matches Kiro's hook stdin JSON payload.
// All hooks receive the same structure; fields are populated based on the event.
type hookInputRaw struct {
	HookEventName string `json:"hook_event_name"`
	CWD           string `json:"cwd"`
	Prompt        string `json:"prompt,omitempty"`
	ToolName      string `json:"tool_name,omitempty"`
	ToolInput     string `json:"tool_input,omitempty"`
	ToolResponse  string `json:"tool_response,omitempty"`
}

// kiroHooksFile represents the .kiro/agents/entire.json structure.
// Entire owns this file entirely — no round-trip preservation needed.
type kiroHooksFile struct {
	AgentSpawn        []kiroHookEntry `json:"agentSpawn,omitempty"`
	UserPromptSubmit  []kiroHookEntry `json:"userPromptSubmit,omitempty"`
	PreToolUse        []kiroHookEntry `json:"preToolUse,omitempty"`
	PostToolUse       []kiroHookEntry `json:"postToolUse,omitempty"`
	Stop              []kiroHookEntry `json:"stop,omitempty"`
}

// kiroHookEntry represents a single hook command in the config file.
type kiroHookEntry struct {
	Command string `json:"command"`
}

// conversationRow represents a row from Kiro's conversations_v2 table.
type conversationRow struct {
	ConversationID string `json:"conversation_id"`
	History        []conversationMessage `json:"history"`
}

// conversationMessage represents a single message in the conversation history.
type conversationMessage struct {
	Role    string        `json:"role"`
	Content []interface{} `json:"content,omitempty"`

	// request_metadata fields (token usage)
	InputTokens  int `json:"input_tokens,omitempty"`
	OutputTokens int `json:"output_tokens,omitempty"`
}

// File modification tools in Kiro
var fileModificationTools = []string{
	"fs_write",
	"str_replace",
	"create_file",
	"write_file",
	"edit_file",
}

package kiro

import (
	"context"
	"io"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Kiro hook names — these become CLI subcommands under `entire hooks kiro`.
// Kiro uses camelCase hook names natively, but CLI subcommands use kebab-case.
const (
	HookNameAgentSpawn       = "agent-spawn"
	HookNameUserPromptSubmit = "user-prompt-submit"
	HookNamePreToolUse       = "pre-tool-use"
	HookNamePostToolUse      = "post-tool-use"
	HookNameStop             = "stop"
)

// HookNames returns the hook verbs Kiro supports.
// These become subcommands: entire hooks kiro <verb>
func (k *KiroAgent) HookNames() []string {
	return []string{
		HookNameAgentSpawn,
		HookNameUserPromptSubmit,
		HookNamePreToolUse,
		HookNamePostToolUse,
		HookNameStop,
	}
}

// ParseHookEvent translates a Kiro hook into a normalized lifecycle Event.
// Returns nil for hooks with no lifecycle significance (preToolUse, postToolUse).
func (k *KiroAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameAgentSpawn:
		return k.parseAgentSpawn(ctx, stdin)
	case HookNameUserPromptSubmit:
		return k.parseUserPromptSubmit(ctx, stdin)
	case HookNameStop:
		return k.parseStop(ctx, stdin)
	case HookNamePreToolUse, HookNamePostToolUse:
		// Pass-through hooks with no lifecycle significance
		return nil, nil //nolint:nilnil // nil event = no lifecycle action
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

func (k *KiroAgent) parseAgentSpawn(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[hookInputRaw](stdin)
	if err != nil {
		return nil, err
	}

	sessionID, sessionRef := k.resolveSession(ctx, raw.CWD)

	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now(),
	}, nil
}

func (k *KiroAgent) parseUserPromptSubmit(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[hookInputRaw](stdin)
	if err != nil {
		return nil, err
	}

	sessionID, sessionRef := k.resolveSession(ctx, raw.CWD)

	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Prompt:     raw.Prompt,
		Timestamp:  time.Now(),
	}, nil
}

func (k *KiroAgent) parseStop(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[hookInputRaw](stdin)
	if err != nil {
		return nil, err
	}

	sessionID, sessionRef := k.resolveSession(ctx, raw.CWD)

	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now(),
	}, nil
}

// resolveSession queries SQLite for the current session ID and builds the
// cached transcript path. Returns ("unknown", "") if the query fails.
func (k *KiroAgent) resolveSession(ctx context.Context, cwd string) (sessionID, sessionRef string) {
	sid, err := k.querySessionID(ctx, cwd)
	if err != nil || sid == "" {
		return "unknown", ""
	}
	ref, err := k.ensureCachedTranscript(ctx, cwd, sid)
	if err != nil {
		return sid, ""
	}
	return sid, ref
}

package kiro

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Ensure KiroAgent implements HookSupport
var _ agent.HookSupport = (*KiroAgent)(nil)

// HooksFileName is the config file for Kiro hooks.
const HooksFileName = "entire.json"

// hooksDir is the directory within .kiro where agent hook configs live.
const hooksDir = "agents"

// entireHookPrefixes identify Entire hooks in the config file.
var entireHookPrefixes = []string{
	"entire ",
	"go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go ",
}

// InstallHooks installs Entire hooks in .kiro/agents/entire.json.
// Since Entire owns this file entirely, we write it from scratch each time.
// Returns the number of hooks installed.
func (k *KiroAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)

	// If hooks are already installed and not forcing, check if they're current
	if !force {
		if existing, readErr := os.ReadFile(hooksPath); readErr == nil { //nolint:gosec // path constructed from repo root
			var file kiroHooksFile
			if json.Unmarshal(existing, &file) == nil && k.allHooksPresent(file, localDev) {
				return 0, nil
			}
		}
	}

	var cmdPrefix string
	if localDev {
		cmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro "
	} else {
		cmdPrefix = "entire hooks kiro "
	}

	file := kiroHooksFile{
		AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
		UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
		PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
		PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
		Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
	}

	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
	}

	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
	if err != nil {
		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
	}

	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
		return 0, fmt.Errorf("failed to write hooks config: %w", err)
	}

	return 5, nil
}

// UninstallHooks removes the Entire hooks config file.
func (k *KiroAgent) UninstallHooks(ctx context.Context) error {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to remove hooks config: %w", err)
	}
	return nil
}

// AreHooksInstalled checks if Entire hooks are installed.
func (k *KiroAgent) AreHooksInstalled(ctx context.Context) bool {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
	if err != nil {
		return false
	}

	var file kiroHooksFile
	if err := json.Unmarshal(data, &file); err != nil {
		return false
	}

	return hasEntireHook(file.AgentSpawn) ||
		hasEntireHook(file.UserPromptSubmit) ||
		hasEntireHook(file.Stop)
}

// GetSupportedHooks returns the hook types Kiro supports.
func (k *KiroAgent) GetSupportedHooks() []agent.HookType {
	return []agent.HookType{
		agent.HookSessionStart,
		agent.HookUserPromptSubmit,
		agent.HookPreToolUse,
		agent.HookPostToolUse,
		agent.HookStop,
	}
}

// allHooksPresent checks if all expected hooks are already in the config.
func (k *KiroAgent) allHooksPresent(file kiroHooksFile, localDev bool) bool {
	var cmdPrefix string
	if localDev {
		cmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro "
	} else {
		cmdPrefix = "entire hooks kiro "
	}

	return hookCommandExists(file.AgentSpawn, cmdPrefix+HookNameAgentSpawn) &&
		hookCommandExists(file.UserPromptSubmit, cmdPrefix+HookNameUserPromptSubmit) &&
		hookCommandExists(file.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
		hookCommandExists(file.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
		hookCommandExists(file.Stop, cmdPrefix+HookNameStop)
}

func hookCommandExists(entries []kiroHookEntry, command string) bool {
	for _, entry := range entries {
		if entry.Command == command {
			return true
		}
	}
	return false
}

func isEntireHook(command string) bool {
	for _, prefix := range entireHookPrefixes {
		if strings.HasPrefix(command, prefix) {
			return true
		}
	}
	return false
}

func hasEntireHook(entries []kiroHookEntry) bool {
	for _, entry := range entries {
		if isEntireHook(entry.Command) {
			return true
		}
	}
	return false
}

// Package kiro implements the Agent interface for Amazon's Kiro CLI.
package kiro

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(AgentNameKiro, NewKiroAgent)
}

// AgentNameKiro is the registry key for Kiro.
const AgentNameKiro types.AgentName = "kiro"

// AgentTypeKiro is the display name stored in metadata/trailers.
const AgentTypeKiro types.AgentType = "Kiro"

// KiroAgent implements the Agent interface for Amazon's Kiro CLI.
//
//nolint:revive // KiroAgent is clearer than Agent in this context
type KiroAgent struct{}

// NewKiroAgent creates a new Kiro agent instance.
func NewKiroAgent() agent.Agent {
	return &KiroAgent{}
}

// --- Identity ---

func (k *KiroAgent) Name() types.AgentName  { return AgentNameKiro }
func (k *KiroAgent) Type() types.AgentType   { return AgentTypeKiro }
func (k *KiroAgent) Description() string     { return "Kiro - Amazon AI coding CLI" }
func (k *KiroAgent) IsPreview() bool         { return true }
func (k *KiroAgent) ProtectedDirs() []string { return []string{".kiro"} }

// DetectPresence checks if Kiro is configured in the repository.
func (k *KiroAgent) DetectPresence(ctx context.Context) (bool, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}
	if _, err := os.Stat(filepath.Join(worktreeRoot, ".kiro")); err == nil {
		return true, nil
	}
	return false, nil
}

// --- Transcript Storage ---

// ReadTranscript reads the cached transcript JSON for a session.
func (k *KiroAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSON transcript into chunks.
// Kiro transcripts are single JSON objects; we use the JSONL chunker since the
// cached format is a JSON blob that fits in a single chunk in most cases.
func (k *KiroAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	if len(content) <= maxSize {
		return [][]byte{content}, nil
	}
	// For large transcripts, split the history array across chunks
	return agent.ChunkJSONL(content, maxSize)
}

// ReassembleTranscript combines transcript chunks back into a single blob.
func (k *KiroAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	if len(chunks) == 1 {
		return chunks[0], nil
	}
	return agent.ReassembleJSONL(chunks), nil
}

// --- Session Management ---

// GetSessionID extracts the session ID from hook input.
func (k *KiroAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// GetSessionDir returns the directory where Kiro stores session data.
// For Kiro, sessions are in SQLite, but we cache transcripts to .entire/tmp/.
func (k *KiroAgent) GetSessionDir(repoPath string) (string, error) {
	return filepath.Join(repoPath, ".entire", "tmp"), nil
}

// ResolveSessionFile returns the path to the cached transcript file.
func (k *KiroAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID+".json")
}

// ReadSession reads session data from the cached transcript.
func (k *KiroAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // Path from agent hook
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  k.Name(),
		SessionRef: input.SessionRef,
		StartTime:  time.Now(),
		NativeData: data,
	}, nil
}

// WriteSession writes session data for resumption.
func (k *KiroAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}
	if session.AgentName != "" && session.AgentName != k.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, k.Name())
	}
	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}
	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
		return fmt.Errorf("failed to create session dir: %w", err)
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}
	return nil
}

// FormatResumeCommand returns the command to resume a Kiro session.
func (k *KiroAgent) FormatResumeCommand(_ string) string {
	return "kiro-cli chat --resume"
}

// GetHookConfigPath returns the path to the hook config file relative to repo root.
func (k *KiroAgent) GetHookConfigPath() string {
	return filepath.Join(".kiro", hooksDir, HooksFileName)
}

// --- SQLite session resolution ---

// dbPath returns the path to Kiro's SQLite database.
func dbPath() string {
	switch runtime.GOOS {
	case "darwin":
		home, _ := os.UserHomeDir()
		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3")
	default: // linux
		home, _ := os.UserHomeDir()
		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3")
	}
}

// querySessionID queries the SQLite database for the most recent conversation ID
// associated with the given CWD.
func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
		return "mock-session-id", nil
	}

	db := dbPath()
	if _, err := os.Stat(db); err != nil {
		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
	}

	query := fmt.Sprintf(
		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
		strings.ReplaceAll(cwd, "'", "''"),
	)

	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
	out, err := cmd.Output()
	if err != nil {
		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
		return "", fmt.Errorf("sqlite3 query failed: %w", err)
	}

	result := strings.TrimSpace(string(out))
	if result == "" || result == "[]" {
		return "", nil
	}

	// sqlite3 -json returns an array of objects
	var rows []map[string]string
	if err := json.Unmarshal([]byte(result), &rows); err != nil {
		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
	}
	if len(rows) == 0 {
		return "", nil
	}

	// The column name from json_extract
	for _, v := range rows[0] {
		return v, nil
	}
	return "", nil
}

// ensureCachedTranscript fetches the conversation from SQLite and caches it
// to .entire/tmp/<sessionID>.json. Returns the cache file path.
func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = cwd
	}

	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
	cachePath := filepath.Join(cacheDir, sessionID+".json")

	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
		// In test mode, return cache path if it exists, or empty
		if _, err := os.Stat(cachePath); err == nil {
			return cachePath, nil
		}
		return cachePath, nil
	}

	db := dbPath()
	query := fmt.Sprintf(
		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
		strings.ReplaceAll(cwd, "'", "''"),
	)

	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
	}

	transcript := strings.TrimSpace(string(out))
	if transcript == "" {
		return "", errors.New("no transcript found")
	}

	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
		return "", fmt.Errorf("failed to create cache dir: %w", err)
	}

	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
		return "", fmt.Errorf("failed to write cached transcript: %w", err)
	}

	return cachePath, nil
}

