140→// saveCommitLinkingAlways persists commit_linking = "always" to settings.local.json.
141→// Uses raw JSON merge to set only the commit_linking field without affecting other
142→// fields. This avoids writing unintended defaults (e.g., enabled: true) when the
143→// local settings file doesn't exist yet.
144→func saveCommitLinkingAlways(ctx context.Context) error {
145→	localPath, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
146→	if err != nil {
147→		return fmt.Errorf("resolving local settings path: %w", err)
148→	}
149→
150→	// Read existing file as raw JSON map to preserve all existing fields.
151→	// If the file doesn't exist, start with an empty map so we only write commit_linking.
152→	var raw map[string]json.RawMessage
153→	data, readErr := os.ReadFile(localPath) //nolint:gosec // path is from AbsPath
154→	if readErr == nil {
155→		if err := json.Unmarshal(data, &raw); err != nil {
156→			return fmt.Errorf("parsing local settings: %w", err)
157→		}
158→	} else if !os.IsNotExist(readErr) {
159→		return fmt.Errorf("reading local settings: %w", readErr)
160→	}
161→	if raw == nil {
162→		raw = make(map[string]json.RawMessage)
163→	}
164→
165→	raw["commit_linking"] = json.RawMessage(`"` + settings.CommitLinkingAlways + `"`)
166→
167→	out, err := json.MarshalIndent(raw, "", "  ")
168→	if err != nil {
169→		return fmt.Errorf("marshaling local settings: %w", err)
170→	}
171→	out = append(out, '\n')
172→
173→	if err := os.MkdirAll(filepath.Dir(localPath), 0o750); err != nil {
174→		return fmt.Errorf("creating settings directory: %w", err)
175→	}
176→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
177→	if err := os.WriteFile(localPath, out, 0o644); err != nil {
178→		return fmt.Errorf("writing local settings: %w", err)
179→	}
180→	return nil
181→}
