183→// CommitMsg is called by the git commit-msg hook after the user edits the message.
184→// If the message contains only our trailer (no actual user content), strip it
185→// so git will abort the commit due to empty message.
186→
187→func (s *ManualCommitStrategy) CommitMsg(_ context.Context, commitMsgFile string) error { //nolint:unparam // error return is part of the hook contract; callers check it
188→	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // Path comes from git hook
189→	if err != nil {
190→		return nil //nolint:nilerr // Hook must be silent on failure
191→	}
192→
193→	message := string(content)
194→
195→	// Check if our trailer is present (ParseCheckpoint validates format, so found==true means valid)
196→	if _, found := trailers.ParseCheckpoint(message); !found {
197→		// No trailer, nothing to do
198→		return nil
199→	}
200→
201→	// Check if there's any user content (non-comment, non-trailer lines)
202→	if !hasUserContent(message) {
203→		// No user content - strip the trailer so git aborts
204→		message = stripCheckpointTrailer(message)
205→		if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil {
206→			return nil //nolint:nilerr // Hook must be silent on failure
207→		}
208→	}
209→
210→	return nil
211→}
212→
213→// hasUserContent checks if the message has any content besides comments and our trailer.
214→func hasUserContent(message string) bool {
215→	trailerPrefix := trailers.CheckpointTrailerKey + ":"
216→	for _, line := range strings.Split(message, "\n") {
217→		trimmed := strings.TrimSpace(line)
218→		// Skip empty lines
219→		if trimmed == "" {
220→			continue
221→		}
222→		// Skip comment lines
223→		if strings.HasPrefix(trimmed, "#") {
224→			continue
225→		}
226→		// Skip our trailer line
227→		if strings.HasPrefix(trimmed, trailerPrefix) {
228→			continue
229→		}
230→		// Found user content
231→		return true
232→	}
233→	return false
234→}
235→
236→// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
237→func stripCheckpointTrailer(message string) string {
238→	trailerPrefix := trailers.CheckpointTrailerKey + ":"
239→	var result []string
240→	for _, line := range strings.Split(message, "\n") {
241→		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
242→			result = append(result, line)
243→		}
244→	}
245→	return strings.Join(result, "\n")
246→}
