248→// isGitSequenceOperation checks if git is currently in the middle of a rebase,
249→// cherry-pick, or revert operation. During these operations, commits are being
250→// replayed and should not be linked to agent sessions.
251→//
252→// Detects:
253→//   - rebase: .git/rebase-merge/ or .git/rebase-apply/ directories
254→//   - cherry-pick: .git/CHERRY_PICK_HEAD file
255→//   - revert: .git/REVERT_HEAD file
256→func isGitSequenceOperation(ctx context.Context) bool {
257→	// Get git directory (handles worktrees and relative paths correctly)
258→	gitDir, err := GetGitDir(ctx)
259→	if err != nil {
260→		return false // Can't determine, assume not in sequence operation
261→	}
262→
263→	// Check for rebase state directories
264→	if _, err := os.Stat(filepath.Join(gitDir, "rebase-merge")); err == nil {
265→		return true
266→	}
267→	if _, err := os.Stat(filepath.Join(gitDir, "rebase-apply")); err == nil {
268→		return true
269→	}
270→
271→	// Check for cherry-pick and revert state files
272→	if _, err := os.Stat(filepath.Join(gitDir, "CHERRY_PICK_HEAD")); err == nil {
273→		return true
274→	}
275→	if _, err := os.Stat(filepath.Join(gitDir, "REVERT_HEAD")); err == nil {
276→		return true
277→	}
278→
279→	return false
280→}
