164→// --- SQLite session resolution ---
165→
166→// dbPath returns the path to Kiro's SQLite database.
167→func dbPath() (string, error) {
168→	home, err := os.UserHomeDir()
169→	if err != nil {
170→		return "", fmt.Errorf("failed to get home directory: %w", err)
171→	}
172→	switch runtime.GOOS {
173→	case "darwin":
174→		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3"), nil
175→	default: // linux
176→		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3"), nil
177→	}
178→}
179→
180→// querySessionID queries the SQLite database for the most recent conversation ID
181→// associated with the given CWD.
182→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
183→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
184→		return "mock-session-id", nil
185→	}
186→
187→	db, err := dbPath()
188→	if err != nil {
189→		return "", err
190→	}
191→	if _, err := os.Stat(db); err != nil {
192→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
193→	}
194→
195→	query := fmt.Sprintf(
196→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
197→		strings.ReplaceAll(cwd, "'", "''"),
198→	)
199→
200→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
201→	out, err := cmd.Output()
202→	if err != nil {
203→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
204→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
205→	}
206→
207→	result := strings.TrimSpace(string(out))
208→	if result == "" || result == "[]" {
209→		return "", nil
210→	}
211→
212→	// sqlite3 -json returns an array of objects
213→	var rows []map[string]string
214→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
215→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
216→	}
217→	if len(rows) == 0 {
218→		return "", nil
219→	}
220→
221→	// The column name from json_extract
222→	for _, v := range rows[0] {
223→		return v, nil
224→	}
225→	return "", nil
226→}
227→
228→// ensureCachedTranscript fetches the conversation from SQLite and caches it
229→// to .entire/tmp/<sessionID>.json. Returns the cache file path.
230→func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
231→	repoRoot, err := paths.WorktreeRoot(ctx)
232→	if err != nil {
233→		repoRoot = cwd
234→	}
235→
236→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
237→	cachePath := filepath.Join(cacheDir, sessionID+".json")
238→
239→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
240→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
241→		// In test mode, return cache path if it exists, or empty
242→		if _, err := os.Stat(cachePath); err == nil {
243→			return cachePath, nil
244→		}
245→		return cachePath, nil
246→	}
247→
248→	db, err := dbPath()
249→	if err != nil {
250→		return "", err
251→	}
252→
253→	query := fmt.Sprintf(
254→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
255→		strings.ReplaceAll(cwd, "'", "''"),
256→	)
257→
258→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
259→	out, err := cmd.Output()
260→	if err != nil {
261→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
262→	}
263→
264→	transcript := strings.TrimSpace(string(out))
265→	if transcript == "" {
266→		return "", errors.New("no transcript found")
267→	}
268→
269→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
270→		return "", fmt.Errorf("failed to create cache dir: %w", err)
271→	}
272→
273→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
274→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
275→	}
276→
277→	return cachePath, nil
278→}
