1095→// filterSessionsWithNewContent returns sessions that have new transcript content
1096→// beyond what was already condensed.
1097→func (s *ManualCommitStrategy) filterSessionsWithNewContent(ctx context.Context, repo *git.Repository, sessions []*SessionState) []*SessionState {
1098→	var result []*SessionState
1099→
1100→	for _, state := range sessions {
1101→		hasNew, err := s.sessionHasNewContent(ctx, repo, state)
1102→		if err != nil {
1103→			// On error, include the session (fail open for hooks)
1104→			result = append(result, state)
1105→			continue
1106→		}
1107→		if hasNew {
1108→			result = append(result, state)
1109→		}
1110→	}
1111→
1112→	return result
1113→}
1114→
1115→// sessionHasNewContent checks if a session has new transcript content
1116→// beyond what was already condensed.
