186→// hasUserContent checks if the message has any content besides comments and our trailer.
187→func hasUserContent(message string) bool {
188→	trailerPrefix := trailers.CheckpointTrailerKey + ":"
189→	for _, line := range strings.Split(message, "\n") {
190→		trimmed := strings.TrimSpace(line)
191→		// Skip empty lines
192→		if trimmed == "" {
193→			continue
194→		}
195→		// Skip comment lines
196→		if strings.HasPrefix(trimmed, "#") {
197→			continue
198→		}
199→		// Skip our trailer line
200→		if strings.HasPrefix(trimmed, trailerPrefix) {
201→			continue
202→		}
203→		// Found user content
204→		return true
205→	}
206→	return false
207→}
208→
209→// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
210→func stripCheckpointTrailer(message string) string {
211→	trailerPrefix := trailers.CheckpointTrailerKey + ":"
212→	var result []string
213→	for _, line := range strings.Split(message, "\n") {
214→		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
215→			result = append(result, line)
216→		}
217→	}
218→	return strings.Join(result, "\n")
219→}
