422→// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
423→// This ensures that when the user commits after rewinding, the next checkpoint will only
424→// include prompts from the rewound point, not prompts from later checkpoints.
425→func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
426→	// Extract session ID from the checkpoint commit's Entire-Session trailer
427→	sessionID, found := trailers.ParseSession(commit.Message)
428→	if !found {
429→		return errors.New("checkpoint has no Entire-Session trailer")
430→	}
431→
432→	// Load session state to get the shadow branch name
433→	state, err := s.loadSessionState(ctx, sessionID)
434→	if err != nil {
435→		return fmt.Errorf("failed to load session state: %w", err)
436→	}
437→	if state == nil {
438→		return fmt.Errorf("session %s not found", sessionID)
439→	}
440→
441→	// Reset the shadow branch to the checkpoint commit
442→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
443→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
444→
445→	// Update the reference to point to the checkpoint commit
446→	ref := plumbing.NewHashReference(refName, commit.Hash)
447→	if err := repo.Storer.SetReference(ref); err != nil {
448→		return fmt.Errorf("failed to update shadow branch: %w", err)
449→	}
450→
451→	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
452→	return nil
453→}
